using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.WireToFrom;
public sealed class ToFromSettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();readonly ComboBox sourceBox=new(){Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};readonly ComboBox staleBox=new(){Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};
 public ToFromSettingsForm(){Text="LSE_ToFrom Settings";StartPosition=FormStartPosition.CenterParent;Size=new Size(1000,640);MinimumSize=new Size(760,520);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,270));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;
  Add(p,"Config JSON (format, layer, blocks, queries)",nameof(s.ConfigPath),s.ConfigPath,r++,"JSON (*.json)|*.json");
  p.RowStyles.Add(new(SizeType.Absolute,40));p.Controls.Add(new Label{Text="Data source",AutoSize=true,Anchor=AnchorStyles.Left},0,r);sourceBox.Items.AddRange(new object[]{"scratch  (project database, read-only through ADODB)","report  (a Wire From/To report saved to a file)"});sourceBox.SelectedIndex=s.DataSource.Equals("report",StringComparison.OrdinalIgnoreCase)?1:0;p.Controls.Add(sourceBox,1,r++);
  p.RowStyles.Add(new(SizeType.Absolute,40));p.Controls.Add(new Label{Text="When drawings are newer than the database",AutoSize=true,Anchor=AnchorStyles.Left},0,r);staleBox.Items.AddRange(new object[]{"warn  (list them in the validation report and continue)","stop  (refuse to run until the database is refreshed)","ignore"});staleBox.SelectedIndex=s.StalePolicy.Equals("stop",StringComparison.OrdinalIgnoreCase)?1:s.StalePolicy.Equals("ignore",StringComparison.OrdinalIgnoreCase)?2:0;p.Controls.Add(staleBox,1,r++);
  Add(p,"Backup folder name (inside the project)",nameof(s.BackupFolderName),s.BackupFolderName,r++);Add(p,"Backups to keep per project",nameof(s.BackupsToKeep),s.BackupsToKeep.ToString(),r++);
  Add(p,"Active project LISP (sets USERS1)",nameof(s.ActiveProjectLisp),s.ActiveProjectLisp,r++);Add(p,"Scratch database path LISP (sets USERS1)",nameof(s.ScratchDbLisp),s.ScratchDbLisp,r++);Add(p,"Refresh project database LISP (run before each read; blank = none)",nameof(s.RefreshDbLisp),s.RefreshDbLisp,r++);
  Check(p,"Show the run report after each run",nameof(s.ShowReportAfterRun),s.ShowReportAfterRun,r++);Check(p,"Current drawing only by default (instead of the whole project)",nameof(s.CurrentDrawingOnly),s.CurrentDrawingOnly,r++);
  var open=new Button{Text="Open config",Dock=DockStyle.Fill};open.Click+=(_,_)=>{try{string path=boxes[nameof(s.ConfigPath)].Text.Trim();if(!File.Exists(path))throw new FileNotFoundException("Config file was not found.",path);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("notepad.exe",'"'+path+'"'){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"LSE_ToFrom Settings");}};
  var save=new Button{Text="Save",Dock=DockStyle.Fill};save.Click+=(_,_)=>{try{s.ConfigPath=boxes[nameof(s.ConfigPath)].Text.Trim();s.BackupFolderName=boxes[nameof(s.BackupFolderName)].Text.Trim();s.ActiveProjectLisp=boxes[nameof(s.ActiveProjectLisp)].Text.Trim();s.ScratchDbLisp=boxes[nameof(s.ScratchDbLisp)].Text.Trim();s.RefreshDbLisp=boxes[nameof(s.RefreshDbLisp)].Text.Trim();
   if(!int.TryParse(boxes[nameof(s.BackupsToKeep)].Text.Trim(),out int keep)||keep<1)throw new InvalidOperationException("Backups to keep must be a whole number of 1 or more.");s.BackupsToKeep=keep;if(s.BackupFolderName.Length==0||s.BackupFolderName.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidOperationException("Backup folder name must be a valid folder name.");
   s.DataSource=sourceBox.SelectedIndex==1?"report":"scratch";s.StalePolicy=staleBox.SelectedIndex==1?"stop":staleBox.SelectedIndex==2?"ignore":"warn";s.ShowReportAfterRun=checks[nameof(s.ShowReportAfterRun)].Checked;s.CurrentDrawingOnly=checks[nameof(s.CurrentDrawingOnly)].Checked;
   if(File.Exists(s.ConfigPath))ConfigService.Load(s.ConfigPath);SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"LSE_ToFrom Settings");}};
  var diag=new Button{Text="Diagnostics",Dock=DockStyle.Fill};diag.Click+=(_,_)=>{using var f=new TextReportForm("LSE_ToFrom Diagnostics",DiagnosticsService.BuildReport());f.ShowDialog(this);};p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(diag,0,r);p.Controls.Add(open,1,r);p.Controls.Add(save,2,r);Controls.Add(p);}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string? browse=null){p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse is null)return;var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{using var f=new OpenFileDialog{Filter=browse,FileName=t.Text};if(f.ShowDialog()==DialogResult.OK)t.Text=f.FileName;};p.Controls.Add(b,2,row);}
 void Check(TableLayoutPanel p,string label,string key,bool value,int row){p.RowStyles.Add(new(SizeType.Absolute,34));var c=new CheckBox{Text=label,Checked=value,AutoSize=true,Anchor=AnchorStyles.Left};checks[key]=c;p.Controls.Add(c,1,row);p.SetColumnSpan(c,2);}
}
